// tools.js - high-resolution voxel tool models (Y-up, +Z forward/muzzle, +X left); RLE data, palette index 0 = empty, n -> palette[n-1]
function r(s, n) { const d = new Uint8Array(n); let i = 0, p = 0; while (p < s.length) { const v = s.charCodeAt(p) - 65; let e = ++p; while (e < s.length && (s.charCodeAt(e) < 65 || s.charCodeAt(e) > 90)) e++; const c = parseInt(s.slice(p, e), 36); d.fill(v, i, i + c); i += c; p = e; } return d; }
function M(name, vs, palette, size, pivot, s) { return { name, voxelSize: vs, palette, parts: [{ name: "main", size, originOffset: [0, 0, 0], pivot, data: r(s, size[0] * size[1] * size[2]) }], anchors: {} }; }

